const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function getByPath(obj, path) {
  if (!obj || !path) return undefined;
  return String(path).split(".").reduce((acc, key) => {
    if (acc === undefined || acc === null) return undefined;
    return acc[key];
  }, obj);
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function normalizeEmail(value) {
  return normalizeString(value).toLowerCase();
}

function normalizeConsent(value, defaultConsentStatus = "not_provided") {
  if (value === true) return "opted_in";
  if (value === false) return "not_provided";

  const normalized = normalizeString(value).toLowerCase();
  if (!normalized) return defaultConsentStatus;

  const optedIn = ["yes", "true", "opted_in", "consented", "subscribed", "i agree", "agree"];
  const optedOut = ["no", "false", "opted_out", "unsubscribed", "do_not_contact"];

  if (optedIn.includes(normalized)) return "opted_in";
  if (optedOut.includes(normalized)) return "opted_out";

  return normalized;
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-N",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        parsed_records: [],
        batch_summary: {
          total_rows_received: 0,
          total_records_parsed: 0,
          empty_rows_skipped: 0,
          source_type: input.config?.source_type || null,
          source_name: input.config?.source_name || null
        },
        c2f_batch_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-N will not parse spreadsheet rows when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "parse_spreadsheet_rows") {
  return fail({
    code: "PARSER_NOT_REQUESTED",
    message: "source.next_action is not parse_spreadsheet_rows.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!Array.isArray(source.rows)) {
  return fail({
    code: "MISSING_ROWS_ARRAY",
    message: "input.rows must be an array."
  });
}

if (!config.field_map || typeof config.field_map !== "object") {
  return fail({
    code: "MISSING_FIELD_MAP",
    message: "config.field_map is required."
  });
}

const fieldMap = config.field_map;
const rows = source.rows;
const startRowNumber = Number(config.start_row_number ?? 1);

let emptyRowsSkipped = 0;

const parsedRecords = rows.map((row, index) => {
  const rowNumber = startRowNumber + index;

  const rawConsent =
    getByPath(row, fieldMap.consent_status) ??
    getByPath(row, fieldMap.consent);

  const record = {
    row_number: rowNumber,
    name: normalizeString(getByPath(row, fieldMap.name)),
    email: normalizeEmail(getByPath(row, fieldMap.email)),
    phone: normalizeString(getByPath(row, fieldMap.phone)),
    company: normalizeString(getByPath(row, fieldMap.company)),
    website: normalizeString(getByPath(row, fieldMap.website)),
    message: normalizeString(getByPath(row, fieldMap.message)),
    source: config.source_name || config.source_type || source.metadata?.filename || "spreadsheet_import",
    consent_status: normalizeConsent(rawConsent, config.default_consent_status || "not_provided"),
    imported_at: source.metadata?.uploaded_at || nowIso()
  };

  const isEmpty = !record.name &&
    !record.email &&
    !record.phone &&
    !record.company &&
    !record.website &&
    !record.message;

  if (isEmpty) {
    emptyRowsSkipped += 1;
    return null;
  }

  const empty_fields = Object.entries(record)
    .filter(([key, value]) =>
      ["name", "email", "phone", "company", "website", "message"].includes(key) && !value
    )
    .map(([key]) => key);

  return {
    record_id: `row_${rowNumber}`,
    row_number: rowNumber,
    payload: record,
    metadata: {
      source_component: source.component_id || null,
      original_event_type: source.event_type || null,
      source_type: config.source_type || null,
      source_name: config.source_name || source.metadata?.filename || null,
      empty_fields,
      parsed_at: nowIso()
    }
  };
}).filter(Boolean);

const c2fBatchHandoff = {
  next_component: "C2-F",
  input: {
    success: true,
    component_id: "C2-N",
    component_version: "v1",
    event_id: source.event_id || null,
    event_type: "parsed_spreadsheet_batch",
    records: parsedRecords,
    metadata: {
      source_component: source.component_id || null,
      original_event_type: source.event_type || null,
      source_type: config.source_type || null,
      source_name: config.source_name || source.metadata?.filename || null,
      total_rows_received: rows.length,
      total_records_parsed: parsedRecords.length,
      empty_rows_skipped: emptyRowsSkipped,
      parsed_at: nowIso()
    },
    error: null,
    next_action: "validate_batch_payload"
  },
  config: {
    validation_rules: config.validation_rules || {
      required_fields: ["name", "email"],
      email_fields: ["email"]
    },
    default_next_action: "dedupe_check"
  }
};

return [
  {
    json: {
      success: true,
      component_id: "C2-N",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      parsed_records: parsedRecords,
      batch_summary: {
        total_rows_received: rows.length,
        total_records_parsed: parsedRecords.length,
        empty_rows_skipped: emptyRowsSkipped,
        source_type: config.source_type || null,
        source_name: config.source_name || source.metadata?.filename || null
      },
      c2f_batch_handoff: c2fBatchHandoff,
      source_result: source,
      error: null,
      next_action: config.default_next_action || "validate_batch_payload"
    }
  }
];
